    type(/^Email/, 'spela@');

    fireEvent.click(screen.getByRole('button', { name: 'Register' }));

    await waitFor(() => expect(field(/^Email/)).toHaveAttribute('aria-invalid', 'true'));
    expect(field(/^Email/)).toHaveAccessibleDescription(/.+/);
    expect(posts()).toHaveLength(0);
